pragma solidity >=0.8.0;

contract StringBytesProbe {
    string public s;
    bytes public b;
    bytes32 public fixedB;
    string[] public arr;

    event Dyn(string indexed marker, string val, bytes data);

    function setConcat(string memory a, string memory c) public returns (string memory) {
        s = string.concat(a, c);
        return s;
    }

    function setBytesConcat(bytes memory x, bytes memory y) public returns (uint256) {
        b = bytes.concat(x, y);
        return b.length;
    }

    function setFixed(bytes32 f) public returns (bytes1) {
        fixedB = f;
        return bytes1(f);
    }

    function pushArr(string memory item) public returns (uint256) {
        arr.push(item);
        return arr.length;
    }

    function getArr(uint256 i) public view returns (string memory) {
        return arr[i];
    }

    function emitDyn(string memory v, bytes memory d) public {
        emit Dyn("m", v, d);
    }
}
